#define MAX 100
int graph[MAX][MAX], visited[MAX], stack[MAX], top=-1;
void dfs(int n, int start) {
    stack[++top]=start;
    while(top>=0){
        int node=stack[top--];
        if(visited[node]) continue;
        visited[node]=1; printf("%d ",node);
        for(int i=n-1;i>=0;i--) if(graph[node][i]&&!visited[i]) stack[++top]=i;
    }
}
